// ─── DB ───────────────────────────────────────────────────
const DB = {
  KEYS: {
    config:     'crd_config',
    challenges: 'crd_challenges',
    questions:  'crd_questions',
    shops:      'crd_shops',
    games:      'crd_games',       // all games (real + fake)
    usedShops:  'crd_used_shops',  // shop ids used today
  },

  // Generic helpers
  _get(key, fallback) {
    try { return JSON.parse(localStorage.getItem(key)) ?? fallback; }
    catch { return fallback; }
  },
  _set(key, val) { localStorage.setItem(key, JSON.stringify(val)); },

  // Config
  loadConfig()    { return Object.assign({}, DEFAULT_CONFIG, this._get(this.KEYS.config, {})); },
  saveConfig(cfg) { this._set(this.KEYS.config, cfg); },

  // Challenges
  // ── CHALLENGES (Supabase) ────────────────────────────────
  async loadChallenges() {
    try {
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), 5000);
      const res = await fetch(
        this.SB_URL + '/rest/v1/challenges?order=id.asc',
        { headers: this._sbHeaders(), signal: controller.signal }
      );
      clearTimeout(timeout);
      if (!res.ok) throw new Error(await res.text());
      const rows = await res.json();
      // Parse data jsonb field if it's a string
      rows.forEach(r => {
        if (r.data && typeof r.data === 'string') {
          try { r.data = JSON.parse(r.data); } catch(e) {}
        }
        // Merge data fields into root for easy access
        if (r.data) Object.assign(r, r.data);
      });
      return rows.length ? rows : DEFAULT_CHALLENGES;
    } catch(err) {
      console.error('Supabase loadChallenges:', err);
      return DEFAULT_CHALLENGES;
    }
  },

  async addChallenge(c) {
    try {
      const res = await fetch(
        this.SB_URL + '/rest/v1/challenges',
        { method:'POST', headers:this._sbHeaders(), body:JSON.stringify(c) }
      );
      if (!res.ok) throw new Error(await res.text());
    } catch(err) { console.error('Supabase addChallenge:', err); }
  },

  async deleteChallenge(id) {
    try {
      const res = await fetch(
        this.SB_URL + '/rest/v1/challenges?id=eq.' + id,
        { method:'DELETE', headers:this._sbHeaders() }
      );
      if (!res.ok) throw new Error(await res.text());
    } catch(err) { console.error('Supabase deleteChallenge:', err); }
  },

  // no-op for compatibility
  async saveChallenges(arr) {},

  // ── QUESTIONS (Supabase) ─────────────────────────────────
  async loadQuestions() {
    try {
      const res = await fetch(
        this.SB_URL + '/rest/v1/questions?order=id.asc',
        { headers: this._sbHeaders() }
      );
      if (!res.ok) throw new Error(await res.text());
      const rows = await res.json();
      return rows.length ? rows : [];
    } catch (err) {
      console.error('Supabase loadQuestions:', err);
      return [];
    }
  },

  async addQuestion(q) {
    try {
      const res = await fetch(
        this.SB_URL + '/rest/v1/questions',
        { method: 'POST', headers: this._sbHeaders(), body: JSON.stringify(q) }
      );
      if (!res.ok) throw new Error(await res.text());
      return await res.json();
    } catch (err) {
      console.error('Supabase addQuestion:', err);
    }
  },

  async deleteQuestion(id) {
    try {
      const res = await fetch(
        this.SB_URL + '/rest/v1/questions?id=eq.' + id,
        { method: 'DELETE', headers: this._sbHeaders() }
      );
      if (!res.ok) throw new Error(await res.text());
    } catch (err) {
      console.error('Supabase deleteQuestion:', err);
    }
  },

  // saveQuestions kept as no-op for compatibility
  async saveQuestions(arr) { /* no-op — use addQuestion/deleteQuestion */ },

  // ── SHOPS (Supabase) ──────────────────────────────────
  async loadShops() {
    try {
      const res = await fetch(
        this.SB_URL + '/rest/v1/shops?order=created_at.asc',
        { headers: this._sbHeaders() }
      );
      if (!res.ok) throw new Error(await res.text());
      const rows = await res.json();
      return rows.length ? rows : DEFAULT_SHOPS;
    } catch (err) {
      console.error('Supabase loadShops:', err);
      return DEFAULT_SHOPS;
    }
  },

  async addShop(shop) {
    try {
      const res = await fetch(
        this.SB_URL + '/rest/v1/shops',
        {
          method:  'POST',
          headers: this._sbHeaders(),
          body:    JSON.stringify({
            name:       shop.name,
            owner_name: shop.ownerName || '',
            logo:       shop.logo || null,
          }),
        }
      );
      if (!res.ok) throw new Error(await res.text());
      return await res.json();
    } catch (err) {
      console.error('Supabase addShop:', err);
    }
  },

  async deleteShop(id) {
    try {
      const res = await fetch(
        this.SB_URL + '/rest/v1/shops?id=eq.' + id,
        { method: 'DELETE', headers: this._sbHeaders() }
      );
      if (!res.ok) throw new Error(await res.text());
    } catch (err) {
      console.error('Supabase deleteShop:', err);
    }
  },

  // saveShops kept as no-op for compatibility (saves are per-item now)
  async saveShops(arr) { /* no-op — use addShop/deleteShop */ },

  // ── SUPABASE ────────────────────────────────────────────
  SB_URL: 'https://bitiljlfgrlewbhwfkkw.supabase.co',
  SB_KEY: 'sb_publishable_paQ3FnKf4QSFiZvYSn-oDQ_lYju1VHb',

  _sbHeaders() {
    return {
      'Content-Type':  'application/json',
      'apikey':        this.SB_KEY,
      'Authorization': 'Bearer ' + this.SB_KEY,
      'Prefer':        'return=representation',
    };
  },

  // Map local game object → Supabase row
  _toRow(entry) {
    return {
      team_name:  entry.teamName  || entry.team_name  || '',
      shop_id:    entry.shopId    || entry.shop_id     || null,
      shop_name:  entry.shopName  || entry.shop_name   || '',
      shop_logo:  entry.shopLogo  || entry.shop_logo   || null,
      owner_name: entry.ownerName || entry.owner_name  || '',
      players:    entry.players   || 0,
      completed:  entry.completed ?? false,
      secs_left:  entry.secsLeft  ?? entry.secs_left   ?? 0,
      points:     entry.points    || 0,
      fake:       entry.fake      || false,
    };
  },

  // Map Supabase row → local game object
  _fromRow(row) {
    return {
      id:        row.id,
      teamName:  row.team_name,
      shopId:    row.shop_id,
      shopName:  row.shop_name,
      shopLogo:  row.shop_logo,
      ownerName: row.owner_name,
      players:   row.players,
      completed: row.completed,
      secsLeft:  row.secs_left,
      points:    row.points,
      fake:      row.fake,
      ts:        row.created_at,
    };
  },

  // Load all games (async) — returns array sorted by created_at desc
  async loadGames() {
    try {
      const res = await fetch(
        this.SB_URL + '/rest/v1/games?order=created_at.desc&limit=200',
        { headers: this._sbHeaders() }
      );
      if (!res.ok) throw new Error(await res.text());
      const rows = await res.json();
      return rows.map(r => this._fromRow(r));
    } catch (err) {
      console.error('Supabase loadGames:', err);
      return [];
    }
  },

  // Add a game row
  async addGame(entry) {
    try {
      const res = await fetch(
        this.SB_URL + '/rest/v1/games',
        {
          method:  'POST',
          headers: this._sbHeaders(),
          body:    JSON.stringify(this._toRow(entry)),
        }
      );
      if (!res.ok) throw new Error(await res.text());
      return await res.json();
    } catch (err) {
      console.error('Supabase addGame:', err);
    }
  },

  // Delete a game by id
  async deleteGame(id) {
    try {
      const res = await fetch(
        this.SB_URL + '/rest/v1/games?id=eq.' + id,
        { method: 'DELETE', headers: this._sbHeaders() }
      );
      if (!res.ok) throw new Error(await res.text());
    } catch (err) {
      console.error('Supabase deleteGame:', err);
    }
  },

  // Today's games only
  async todayGames() {
    try {
      const today = new Date();
      today.setHours(0,0,0,0);
      const iso  = today.toISOString();
      const res  = await fetch(
        this.SB_URL + '/rest/v1/games?created_at=gte.' + iso + '&order=points.desc',
        { headers: this._sbHeaders() }
      );
      if (!res.ok) throw new Error(await res.text());
      const rows = await res.json();
      return rows.map(r => this._fromRow(r));
    } catch (err) {
      console.error('Supabase todayGames:', err);
      return [];
    }
  },

  // Ranking: today sorted by points desc
  async todayRanking() {
    const games = await this.todayGames();
    return games
      .sort((a, b) => b.points - a.points)
      .map((g, i) => ({ ...g, rank: i + 1 }));
  },

  // Used shops today (to avoid re-drawing same shops)
  loadUsedShops() {
    // Reset if stored date is not today
    const stored = this._get(this.KEYS.usedShops, { date: '', ids: [] });
    const today  = new Date().toDateString();
    if (stored.date !== today) return [];
    return stored.ids;
  },

  markShopUsed(shopId) {
    const today = new Date().toDateString();
    const used  = this.loadUsedShops();
    if (!used.includes(shopId)) used.push(shopId);
    this._set(this.KEYS.usedShops, { date: today, ids: used });
  },

  resetUsedShops() {
    this._set(this.KEYS.usedShops, { date: new Date().toDateString(), ids: [] });
  },

  // Draw 3 random shops not yet used today
  async draw3Shops() {
    const all = await this.loadShops();
    if (all.length === 0) return [];
    let used  = this.loadUsedShops();
    let avail = all.filter(s => !used.includes(s.id));
    if (avail.length < 3) {
      this.resetUsedShops();
      avail = all;
    }
    const shuffled = [...avail].sort(() => Math.random() - 0.5);
    return shuffled.slice(0, Math.min(3, shuffled.length));
  },

  // Reset local config/shops (does NOT delete games from Supabase)
  resetAll() {
    [this.KEYS.config, this.KEYS.challenges,
     this.KEYS.usedShops].forEach(k => localStorage.removeItem(k));
  },
};

// ─── BOARD ────────────────────────────────────────────────
const SIDE_PAT = ['corner','challenge','question','question','challenge','question','question','challenge','corner'];

function buildBoard() {
  const board = [];
  for (let i = 0; i < 32; i++) {
    let sp;
    if      (i <= 8)  sp = i;
    else if (i <= 16) sp = i - 8;
    else if (i <= 24) sp = i - 16;
    else              sp = i - 24;
    board.push({ id: i, type: SIDE_PAT[sp] });
  }
  return board;
}
const BOARD = buildBoard();

